// ── Types ──────────────────────────────────────────────────────────────────

export type MealType =
  | "petit-dej"
  | "dejeuner"
  | "diner"
  | "collation"
  | "pre-training"
  | "post-training"
  | "dessert";

export type Diet = "omnivore" | "vegetarien" | "vegan" | "pescetarien";

export type Phase = "surplus" | "maintenance" | "deficit";

export type Season = "printemps" | "ete" | "automne" | "hiver" | "toute-saison";

export type Temp = "chaud" | "froid" | "tiede";

export type Allergen =
  | "gluten"
  | "lactose"
  | "oeuf"
  | "fruits-a-coque"
  | "poisson"
  | "crustaces"
  | "soja"
  | "arachide";

export interface Recipe {
  id: string;
  name: string;
  meal: MealType;
  diet: Diet[];
  phases: Phase[];
  season: Season[];
  temp: Temp;
  texture: string[];
  price: 1 | 2 | 3; // € / €€ / €€€
  region: string;
  prepMinutes: number;
  kcal: number;
  protein: number;
  carbs: number;
  fat: number;
  allergens: Allergen[];
  ingredients: string[];
  steps: string[];
  tip: string;
  /** Recette signature réservée — débloquée par l'abonnement ou par rang (voir lib/gamification.ts). */
  exclusive?: boolean;
}

// ── Labels pour l'UI ──────────────────────────────────────────────────────

